<template><section class="expert-autofill expert-device-search"><h3>Buscador experto de equipos</h3><p>Consulta cualquier equipo, aunque no esté en tu catálogo: computadoras, impresoras, cámaras, redes, servidores y otros dispositivos.</p><div class="expert-fields expert-diagnostic-filters"><label>Tipo de equipo<select v-model="family" @change="symptom=options[0]"><option value="printer">Impresora</option><option value="pc">Computadora</option><option value="laptop">Laptop</option><option value="other">Otro equipo</option></select></label><label>Sintoma principal<select v-model="symptom"><option v-for="option in options" :key="option">{{option}}</option></select></label><label>Objetivo<select v-model="goal"><option>Resolver una falla</option><option>Mantenimiento preventivo</option><option>Evaluar necesidad de reseteo</option><option>Buscar procedimiento y video</option></select></label><label>Codigo de error / luces<button type="button" class="expert-search-dictate" :disabled="!voiceSupported||busy" :aria-label="(dictating==='errorCode'?'Detener dictado de ':'Dictar ') + voiceLabels.errorCode" :aria-pressed="dictating==='errorCode'" @click.prevent="dictate('errorCode')">{{dictating==='errorCode'?'Detener':'Dictar por voz'}}</button><input v-model="errorCode" maxlength="200" placeholder="Ej. E-11, luz de papel, pitidos..."></label></div><div class="expert-fields"><label>Equipo, marca o nombre<button type="button" class="expert-search-dictate" :disabled="!voiceSupported||busy" :aria-label="(dictating==='query'?'Detener dictado de ':'Dictar ') + voiceLabels.query" :aria-pressed="dictating==='query'" @click.prevent="dictate('query')">{{dictating==='query'?'Detener':'Dictar por voz'}}</button><input v-model="query" placeholder="Ej. impresora Epson L3250, router o cámara" maxlength="300"></label><label>Modelo exacto, si lo conoces<button type="button" class="expert-search-dictate" :disabled="!voiceSupported||busy" :aria-label="(dictating==='model'?'Detener dictado de ':'Dictar ') + voiceLabels.model" :aria-pressed="dictating==='model'" @click.prevent="dictate('model')">{{dictating==='model'?'Detener':'Dictar por voz'}}</button><input v-model="model" placeholder="Modelo del equipo a investigar" maxlength="200"></label></div><label>Problema o consulta técnica<button type="button" class="expert-search-dictate" :disabled="!voiceSupported||busy" :aria-label="(dictating==='question'?'Detener dictado de ':'Dictar ') + voiceLabels.question" :aria-pressed="dictating==='question'" @click.prevent="dictate('question')">{{dictating==='question'?'Detener':'Dictar por voz'}}</button><textarea v-model="question" rows="2" maxlength="4000" placeholder="Ej. No imprime, pierde conexión o muestra un código de error."></textarea></label><label>Pruebas o mantenimiento ya realizados<button type="button" class="expert-search-dictate" :disabled="!voiceSupported||busy" :aria-label="(dictating==='attempted'?'Detener dictado de ':'Dictar ') + voiceLabels.attempted" :aria-pressed="dictating==='attempted'" @click.prevent="dictate('attempted')">{{dictating==='attempted'?'Detener':'Dictar por voz'}}</button><textarea v-model="attempted" rows="2" maxlength="2000" placeholder="Ej. prueba de inyectores, limpieza, otro cable, reinicio..."></textarea></label><button type="button" :disabled="busy||!query.trim()||!settings" @click="search">{{busy?'Investigando equipo…':'Buscar solución técnica'}}</button><p v-if="voiceMessage" class="expert-note" role="status">{{voiceMessage}}</p><p v-if="!voiceSupported" class="expert-note">Tu navegador no ofrece dictado. Puedes escribir o usar Chrome o Edge con acceso al microfono.</p><p v-if="error" class="expert-error" role="alert">{{error}}</p><section v-if="answer"><h4>Orientación técnica del equipo</h4><p class="expert-output">{{answer}}</p><section v-if="causes.length"><h4>Posibles causas</h4><ul><li v-for="(cause,i) in causes" :key="i">{{cause}}</li></ul></section><section v-if="steps.length"><h4>Procedimiento recomendado</h4><ol><li v-for="(step,i) in steps" :key="i">{{step}}</li></ol></section><section v-if="reset.decision" class="expert-reset-guide"><h4>Reinicio o reseteo: {{reset.decision}}</h4><dl><dt>Cuando corresponde</dt><dd>{{reset.when}}</dd><dt>Cuando evitarlo</dt><dd>{{reset.avoid}}</dd><dt>Procedimiento y requisitos</dt><dd>{{reset.procedure}}</dd><dt>Precauciones y respaldo</dt><dd>{{reset.risks}}</dd></dl></section><section class="expert-procedure-videos"><h4>Videos para el procedimiento</h4><article v-for="(video,i) in videos" :key="video.url"><strong>{{i===0?'Primera referencia recomendada':'Otra referencia'}}</strong><a :href="video.url" target="_blank" rel="noopener noreferrer">{{video.title||'Ver video en YouTube'}}</a><small>{{video.channel}} - {{matchLabel(video.match)}}</small><p>{{video.reason}}</p></article><p v-if="!videos.length">No se encontraron enlaces de videos verificados adecuados para esta consulta.</p><a :href="videoSearch" target="_blank" rel="noopener noreferrer">Buscar en YouTube por modelo y problema</a></section><details><summary>Fuentes tecnicas consultadas</summary><ul><li v-for="source in sources" :key="source.url"><a :href="source.url" target="_blank" rel="noopener noreferrer">{{source.title||source.url}}</a></li></ul></details><button type="button" @click="$emit('use',{equipment:query,model,request:diagnosticRequest})">Usar equipo y consulta en el diagnóstico</button></section></section></template>
<script>
export default {props:{settings:Object,active:{type:Boolean,default:true}},data(){return {voiceSupported:!!(window.SpeechRecognition||window.webkitSpeechRecognition),dictating:'',voiceMessage:'',voiceLabels:{errorCode:'codigo de error',query:'equipo',model:'modelo',question:'problema tecnico',attempted:'pruebas realizadas'},family:'printer',symptom:'No imprime',goal:'Resolver una falla',errorCode:'',attempted:'',causes:[],steps:[],reset:{},videos:[],query:'',model:'',question:'',answer:'',sources:[],busy:false,error:''}},computed:{diagnosticRequest(){return [this.goal,this.symptom,this.errorCode?'Codigo: '+this.errorCode:'',this.question,this.attempted?'Pruebas reportadas: '+this.attempted:''].filter(Boolean).join('. ')},options(){return {printer:['No imprime','Imprime con rayas o colores incorrectos','Atasco o no toma papel','No conecta por USB o WiFi','Luces o codigo de error','Almohadillas o caja de mantenimiento','Mantenimiento preventivo'],pc:['No enciende','Sin imagen o pitidos','Lentitud o reinicios','Sobrecalentamiento','Falla de disco o sistema','Mantenimiento preventivo'],laptop:['No enciende o no carga','Pantalla negra','Sobrecalentamiento o apagados','Bateria o cargador','Teclado, WiFi o puertos','Mantenimiento preventivo'],other:['Falla de funcionamiento','Conexion o configuracion','Codigo de error','Mantenimiento preventivo']}[this.family]},videoSearch(){return 'https://www.youtube.com/results?search_query='+encodeURIComponent([this.query,this.model,this.symptom,this.errorCode,'procedimiento'].filter(Boolean).join(' '))}},watch:{active(value){if(!value)this.stopDictation()}},beforeDestroy(){this.stopDictation();if(this.controller)this.controller.abort()},methods:{stopDictation(){if(this.recognition){this.recognition.onend=null;this.recognition.onresult=null;this.recognition.onerror=null;this.recognition.stop();this.recognition=null}this.dictating=''},dictate(field){if(this.dictating===field){this.stopDictation();this.voiceMessage='Dictado detenido.';return}this.stopDictation();this.$emit('dictation-start');const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition)return;const recognition=new Recognition;this.recognition=recognition;recognition.lang='es-PE';recognition.continuous=true;recognition.interimResults=false;this.dictating=field;this.voiceMessage='Escuchando '+this.voiceLabels[field]+'. Pulsa Detener al terminar.';recognition.onresult=event=>{if(this.recognition!==recognition)return;let text='';for(let i=event.resultIndex;i<event.results.length;i++)if(event.results[i].isFinal)text+=event.results[i][0].transcript+' ';const limits={errorCode:200,query:300,model:200,question:4000,attempted:2000};if(text.trim())this[field]=(this[field]+' '+text.trim()).trim().slice(0,limits[field])};recognition.onerror=event=>{this.voiceMessage=event.error==='not-allowed'?'Permite el microfono en el navegador para dictar.':event.error==='no-speech'?'No se detecto voz. Puedes volver a dictar.':'No se pudo continuar el dictado. Intenta nuevamente.';this.stopDictation()};recognition.onend=()=>{if(this.recognition===recognition){this.dictating='';this.recognition=null;this.voiceMessage='Dictado finalizado. Revisa el texto antes de consultar.'}};try{recognition.start()}catch(e){this.stopDictation();this.voiceMessage='No se pudo iniciar el microfono.'}},matchLabel(match){return {exact:'Modelo exacto',family:'Familia similar: confirmar diferencias',general:'Procedimiento general'}[match]||'Confirmar modelo'},async search(){this.stopDictation();this.busy=true;this.error='';this.answer='';this.sources=[];this.causes=[];this.steps=[];this.reset={};this.videos=[];this.controller=new AbortController;const timer=setTimeout(()=>this.controller.abort(),160000);try{const response=await fetch('/api/index.php/ali/tecnico',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Ali-CSRF':this.settings.csrf},body:JSON.stringify({action:'expert_lookup',query:this.query,model:this.model,question:this.question,family:this.family,symptom:this.symptom,goal:this.goal,error_code:this.errorCode,attempted:this.attempted}),signal:this.controller.signal});const result=await response.json();if(!response.ok)throw Error(result.error||'No se pudo investigar el equipo.');this.answer=result.text;this.sources=result.sources||[];this.causes=result.causes||[];this.steps=result.steps||[];this.reset=result.reset||{};this.videos=result.videos||[]}catch(e){this.error=e.name==='AbortError'?'La consulta tardó demasiado. Intenta nuevamente.':e.message}finally{clearTimeout(timer);this.busy=false}}}}
</script>

<style>.expert-reset-guide{padding:14px;border:1px solid #e8d49a;background:#fffaf0;border-radius:12px;margin:16px 0}.expert-reset-guide dt{font-size:13px;margin-top:10px}.expert-reset-guide dd{margin:4px 0;white-space:pre-wrap}.expert-procedure-videos article{display:flex;flex-direction:column;gap:6px;padding:12px;border:1px solid #d6def4;border-radius:10px;margin:10px 0;background:white}.expert-procedure-videos article>strong{color:#5145ad;font-size:12px}.expert-procedure-videos a{overflow-wrap:anywhere}.expert-device-search h4{font-size:17px;margin:18px 0 10px}.expert-device-search li{margin:8px 0}.expert-device-search .expert-diagnostic-filters{margin-bottom:16px}.expert-device-search .expert-search-dictate{display:block;width:auto;margin:5px 0 8px;padding:5px 10px;font-size:12px;border:1px solid #becbed;background:white;color:#5145ad;border-radius:8px}.expert-device-search .expert-search-dictate[aria-pressed=true]{background:#ffe6eb;color:#a21c38;border-color:#e8889d}
</style>
